package com.mamtrex.hospital.patient; import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*; import java.time.LocalDate; @Entity @Table(name="patients", indexes={@Index(name="idx_patient_mrn",columnList="medicalRecordNumber",unique=true)}) public class Patient extends BaseEntity { @Column(nullable=false,unique=true) private String medicalRecordNumber; @Column(nullable=false) private String fullName; private LocalDate dateOfBirth; private String sex; private String phone; private String email; private String nationalId; @Column(length=1000) private String address; private boolean active=true; protected Patient(){} public Patient(String mrn,String name,LocalDate dob,String sex,String phone,String email,String nationalId,String address){medicalRecordNumber=mrn;fullName=name;dateOfBirth=dob;this.sex=sex;this.phone=phone;this.email=email;this.nationalId=nationalId;this.address=address;} public String getMedicalRecordNumber(){return medicalRecordNumber;} public String getFullName(){return fullName;} public LocalDate getDateOfBirth(){return dateOfBirth;} public String getSex(){return sex;} public String getPhone(){return phone;} public String getEmail(){return email;} public String getNationalId(){return nationalId;} public String getAddress(){return address;} public boolean isActive(){return active;} public void update(String name,String phone,String email,String address){fullName=name;this.phone=phone;this.email=email;this.address=address;} }
